}).reset_index()
yearly.columns = ['Year', 'Petrol (USD/L)', 'Diesel (USD/L)', 'LPG (USD/L)', 'Brent Crude (USD/bbl)']
yearly = yearly.round(3)

# Volatility by period - COVID (2020), Recovery (2021), Energy Crisis (2022), Normalization (2023-2026)
def get_period(year):
    if year == 2020: return 'COVID Shock (2020)'
    elif year == 2021: return 'Recovery (2021)'
    elif year == 2022: return 'Energy Crisis (2022)'
    else: return f'Stable/Mixed ({year})'

