#!/usr/bin/env python3
"""
Global Fuel Price Trends & Policy Impact Analysis (2020–2026)
Generates a comprehensive HTML report from data.csv
"""

import pandas as pd
import numpy as np
from datetime import datetime
import os

# Create output directory
os.makedirs('/app/output', exist_ok=True)

# Load data
print("Loading data...")
df = pd.read_csv('/app/benchmark/data.csv')
df['date'] = pd.to_datetime(df['date'])

print(f"Dataset: {len(df):,} rows, {df['country'].nunique()} countries, {df['date'].min().date()} to {df['date'].max().date()}")

# =============================================================================
# GLOBAL STATISTICS
# =============================================================================
print("Computing global statistics...")

overall_avg_petrol = df['petrol_usd_liter'].mean()
overall_avg_diesel = df['diesel_usd_liter'].mean()
overall_avg_lpg = df['lpg_usd_liter'].mean()
overall_avg_brent = df['brent_crude_usd'].mean()

petrol_min = df['petrol_usd_liter'].min()
petrol_max = df['petrol_usd_liter'].max()
diesel_min = df['diesel_usd_liter'].min()
diesel_max = df['diesel_usd_liter'].max()
lpg_min = df['lpg_usd_liter'].min()
lpg_max = df['lpg_usd_liter'].max()
brent_min = df['brent_crude_usd'].min()
brent_max = df['brent_crude_usd'].max()

# =============================================================================
# TEMPORAL TRENDS & VOLATILITY
# =============================================================================
print("Computing temporal trends...")

df['year'] = df['date'].dt.year
df['month'] = df['date'].dt.month
df['year_month'] = df['date'].dt.to_period('M')

# Yearly averages
yearly = df.groupby('year').agg({
    'petrol_usd_liter': 'mean',
    'diesel_usd_liter': 'mean',
    'lpg_usd_liter': 'mean',
    'brent_crude_usd': 'mean'
}).reset_index()
yearly.columns = ['Year', 'Petrol (USD/L)', 'Diesel (USD/L)', 'LPG (USD/L)', 'Brent Crude (USD/bbl)']
yearly = yearly.round(3)

# Volatility by period - COVID (2020), Recovery (2021), Energy Crisis (2022), Normalization (2023-2026)
def get_period(year):
    if year == 2020: return 'COVID Shock (2020)'
    elif year == 2021: return 'Recovery (2021)'
    elif year == 2022: return 'Energy Crisis (2022)'
    else: return f'Stable/Mixed ({year})'

df['period'] = df['year'].apply(get_period)
period_stats = df.groupby('period').agg({
    'petrol_usd_liter': ['mean', 'std'],
    'diesel_usd_liter': ['mean', 'std'],
    'brent_crude_usd': ['mean', 'std']
}).round(3)

# Monthly Brent-Petrol correlation
monthly = df.groupby('date').agg({
    'petrol_usd_liter': 'mean',
    'diesel_usd_liter': 'mean',
    'brent_crude_usd': 'mean'
}).reset_index()

brent_petrol_corr = monthly['brent_crude_usd'].corr(monthly['petrol_usd_liter'])
brent_diesel_corr = monthly['brent_crude_usd'].corr(monthly['diesel_usd_liter'])

# Calculate coefficient of variation for volatility comparison
petrol_cv = (df.groupby('date')['petrol_usd_liter'].mean().std() / df.groupby('date')['petrol_usd_liter'].mean().mean()) * 100

# =============================================================================
# REGIONAL COMPARISON
# =============================================================================
print("Computing regional comparison...")

region_yearly = df.groupby(['region', 'year']).agg({
    'petrol_usd_liter': 'mean',
    'diesel_usd_liter': 'mean'
}).reset_index()

region_avg = df.groupby('region').agg({
    'petrol_usd_liter': 'mean',
    'diesel_usd_liter': 'mean',
    'lpg_usd_liter': 'mean'
}).round(3)

region_avg = region_avg.sort_values('petrol_usd_liter', ascending=False)

# Regional price spread by year
regional_spread = df.groupby('year').apply(
    lambda x: x.groupby('region')['petrol_usd_liter'].mean().max() - x.groupby('region')['petrol_usd_liter'].mean().min()
).reset_index()
regional_spread.columns = ['Year', 'Price Spread (USD/L)']

# =============================================================================
# SUBSIDY AND TAXATION ANALYSIS
# =============================================================================
print("Computing subsidy and tax analysis...")

subsidy_avg = df.groupby('subsidy_level').agg({
    'petrol_usd_liter': 'mean',
    'diesel_usd_liter': 'mean',
    'tax_percentage': 'mean'
}).round(3)

# Subsidy dampening effect
high_sub_petrol = df[df['subsidy_level'] == 'High']['petrol_usd_liter'].mean()
low_sub_petrol = df[df['subsidy_level'] == 'Low']['petrol_usd_liter'].mean()
subsidy_dampening = ((low_sub_petrol - high_sub_petrol) / low_sub_petrol) * 100

# By income level and subsidy
income_subsidy = df.groupby(['income_level', 'subsidy_level']).agg({
    'petrol_usd_liter': 'mean',
    'diesel_usd_liter': 'mean',
    'tax_percentage': 'mean'
}).round(3)

# =============================================================================
# INCOME LEVEL ANALYSIS
# =============================================================================
print("Computing income level analysis...")

income_avg = df.groupby('income_level').agg({
    'petrol_usd_liter': 'mean',
    'diesel_usd_liter': 'mean',
    'lpg_usd_liter': 'mean',
    'tax_percentage': 'mean',
    'country': 'nunique'
}).round(3)
income_avg.columns = ['Petrol (USD/L)', 'Diesel (USD/L)', 'LPG (USD/L)', 'Tax %', 'Countries']

# Tax-to-price ratio by income
tax_by_income = df.groupby('income_level')['tax_percentage'].mean().round(2)

# =============================================================================
# KEY STATS FOR FINDINGS
# =============================================================================
# Countries count
countries_84 = df['country'].nunique() == 84

# Highest and lowest price regions
highest_region = region_avg.index[0]
lowest_region = region_avg.index[-1]
highest_price = region_avg.iloc[0]['petrol_usd_liter']
lowest_price = region_avg.iloc[-1]['petrol_usd_liter']

# Peak volatility period
yearly_petrol_std = df.groupby('year')['petrol_usd_liter'].std()
peak_volatility_year = yearly_petrol_std.idxmax()

# Correlation strength interpretation
def interpret_correlation(r):
    r = abs(r)
    if r >= 0.9: return "very strong"
    elif r >= 0.7: return "strong"
    elif r >= 0.5: return "moderate"
    elif r >= 0.3: return "weak"
    else: return "very weak"

# =============================================================================
# GENERATE HTML REPORT
# =============================================================================
print("Generating HTML report...")

